def cobs_encode(data):
    if not data:
        return b'\x01'
    result = bytearray()
    i = 0
    n = len(data)
    while i < n:
        code = 1
        j = i
        while j < n and code < 255 and data[j] != 0:
            code += 1
            j += 1
        result.append(code)
        result.extend(data[i:j])
        i = j + 1 if j < n and data[j] == 0 else j
    return bytes(result)

def cobs_decode(data):
    if not data or any(b == 0 for b in data):
        raise ValueError
    result = bytearray()
    i = 0
    n = len(data)
    while i < n:
        code = data[i]
        if code == 0:
            raise ValueError
        i += 1
        if i + code - 1 > n:
            raise ValueError
        result.extend(data[i:i + code - 1])
        i += code - 1
        if code < 255:
            result.append(0)
    return bytes(result)
